SELECT se.name, t.n, t.r FROM (SELECT x.seller_id, COUNT(*) AS n, SUM(x.late) * 1.0 / COUNT(*) AS r FROM ( SELECT DISTINCT oi.seller_id, sh.shipment_id, CASE WHEN CAST(sh.delivered_at_utc + INTERVAL 6 HOUR AS DATE) > sh.promised_date THEN 1 ELSE 0 END AS late FROM shipments sh JOIN order_items oi ON oi.order_id = sh.order_id WHERE sh.delivered_at_utc IS NOT NULL AND sh.order_id IN (SELECT order_id FROM orders WHERE is_deleted = FALSE) AND sh.delivered_at_utc >= TIMESTAMP '2026-07-01 00:00:00' - INTERVAL 6 HOUR AND sh.delivered_at_utc < TIMESTAMP '2026-10-01 00:00:00' - INTERVAL 6 HOUR) x GROUP BY x.seller_id HAVING COUNT(*) >= 200) t JOIN sellers se ON se.seller_id = t.seller_id ORDER BY t.r DESC LIMIT 1
